from __future__ import annotations
import base64, shutil
from datetime import datetime
from pathlib import Path

MODULE="alliance_autonomous_student_v433.py"
REG="alliance_optional_property_modules.py"
DATA=""

def chk(p): compile(p.read_text(encoding="utf-8"),str(p),"exec")

def main():
    r=Path.cwd()
    req=["alliance_autonomous_student_v432.py","alliance_autonomous_student_v431.py","alliance_autonomous_student_v430.py",
         "alliance_acquisition_intent_closure_v425.py","alliance_automation_grammar_rescue_v423.py",
         "alliance_automation_closure_v422.py","alliance_automation_truth_escalator_v421.py",
         "alliance_automation_machine_v420.py","alliance_cre_championship_v410.py",
         "alliance_cre_academy_v402.py","alliance_cre_academy_v401.py","alliance_cre_academy_v400.py",REG]
    miss=[x for x in req if not (r/x).exists()]
    if miss: raise SystemExit("Missing cumulative files: "+", ".join(miss))

    v432=(r/"alliance_autonomous_student_v432.py").read_text(encoding="utf-8")
    for marker in ['VERSION = "4.3.2-ALLIANCE-AUTONOMOUS-STUDENT-V5-FINAL-TRAINING-REPAIR"',
                   "V432_MIXED_PARENT_FINAL_PRECEDENCE","V432_TRAINING_HOLD_DO_NOT_FREEZE_V5"]:
        if marker not in v432: raise SystemExit("Current 4.3.2 source differs; refusing blind install: "+marker)

    reg=r/REG; old=reg.read_text(encoding="utf-8")
    bak=r/f"{REG}.before-v433-{datetime.now().strftime('%Y%m%d-%H%M%S')}.bak"
    shutil.copy2(reg,bak)
    (r/MODULE).write_text(base64.b64decode(DATA).decode(),encoding="utf-8")

    marker="# FOUNDATION 4.3.3 - Alliance Requirement Grammar Closure"
    if marker not in old:
        pos=old.rfind("    return result")
        if pos<0: raise SystemExit("Registrar return not found; no changes made.")
        block=r"""
    # FOUNDATION 4.3.3 - Alliance Requirement Grammar Closure
    # Additive only. Fresh V5 remains protected until all cumulative gates PASS.
    try:
        if _route_exists(app, "/api/property-brain/autonomous-v433/status"):
            result["autonomous_v433"] = {"status":"ALREADY_REGISTERED","route":"/property-brain/autonomous-v433","error":None}
        else:
            import alliance_autonomous_student_v433 as autonomous_v433
            result["autonomous_v433"] = {**autonomous_v433.register(core), "error": None}
    except Exception as exc:
        result["autonomous_v433"] = {"status":"ERROR","error":f"{type(exc).__name__}: {exc}","route":"/property-brain/autonomous-v433","fail_safe":True}

"""
        reg.write_text(old[:pos]+block+old[pos:],encoding="utf-8")

    chk(r/MODULE); chk(reg)
    txt=reg.read_text(encoding="utf-8")
    checks={"v402":"academy_v402" in txt,"v410":"championship_v410" in txt,"v420":"automation_v420" in txt,
             "v421":"automation_v421" in txt,"v422":"automation_v422" in txt,"v423":"automation_v423" in txt,
             "v425":"automation_v425" in txt,"v430":"autonomous_v430" in txt,"v431":"autonomous_v431" in txt,
             "v432":"autonomous_v432" in txt,"v433":"autonomous_v433" in txt}
    if not all(checks.values()): raise SystemExit("Cumulative verification failed: "+repr(checks))

    print("Alliance Autonomous Student 4.3.3 installed")
    print("Fixes: require/requires demand grammar + strict same-clause transaction relation")
    print("No adjacent-clause rent leakage")
    print("4.3.0/4.3.1/4.3.2 preserved")
    print("Fresh V5 freezes automatically only after cumulative PASS")
    print("Student excluded from V5 truth judges")
    print("Production/WhatsApp/Gold writes: 0")
    print("Dashboard: /property-brain/autonomous-v433")
    print("Backup:",bak)

if __name__=="__main__":
    main()
